	protected DBTraceAddressSnapRangePropertyMapSpace<byte[], DBTraceRegisterContextEntry>
			getRegisterValueMap(
					Language language, Register register, bool createIfAbsent) {
		ImmutablePair<Language, Register> pair = new(language, register);
		DBTraceGuestLanguage guest = manager.languageManager.getLanguageByLanguage(language);
		if (createIfAbsent) {
			return registerValueMaps.computeIfAbsent(pair, t => {
				try {
					DBTraceRegisterEntry ent = registerStore.create();
					ent.set(guest, register);
					return createRegisterValueMap(t);
				}
				catch (VersionException e) {
					throw new AssertionError(e);
				}
			});
		}
		return registerValueMaps.get(pair);
