	/* @Override */
	public bool hasRegisterValueInAddressRange(Language language, Register register, long snap,
			AddressRange within) {
		using (LockHold hold = LockHold.@lock(@lock.readLock()))
{
			Register @base = register.getBaseRegister();
			DBTraceAddressSnapRangePropertyMapSpace<byte[],object> valueMap =
				getRegisterValueMap(language, register, false);
			if (valueMap == null) {
				return false;
			}
			foreach (Entry<TraceAddressSnapRange, byte[]> entry in valueMap.reduce(
				TraceAddressSnapRangeQuery.intersecting(within, Lifespan.at(snap))).entries()) {
				RegisterValue baseValue = new RegisterValue(@base, entry.getValue());
				if (baseValue.getRegisterValue(register).hasAnyValue()) {
					return true;
				}
			}
			return false;
		}
	}

